#!/usr/bin/env bash
# Enforces the commit message convention from AGENTS.md section 2.1.
#
# Usage: scripts/check-commit-msg.sh COMMIT_MSG_FILE
#
# Subject: `feat(<scope>): <summary>` or `ref(<scope>): <summary>`.
# Body: at least one `- ` bullet listing the completed tasks.
#
# Merge and revert commits generated by Git are accepted unchanged.
set -u

if [ "$#" -ne 1 ]; then
  echo "usage: check-commit-msg.sh COMMIT_MSG_FILE" >&2
  exit 2
fi

message="$1"
if [ ! -f "$message" ]; then
  echo "check-commit-msg.sh: no such file: $message" >&2
  exit 2
fi

subject=$(grep -v -E '^[[:space:]]*(#|$)' "$message" | head -n 1)
case "$subject" in
  Merge\ *|Revert\ *) exit 0 ;;
esac

subject_pattern='^(feat|ref)\([a-z0-9][a-z0-9._/-]*\): .+$'
if ! printf '%s\n' "$subject" | grep -q -E "$subject_pattern"; then
  echo "Rejected: commit subject must follow" >&2
  echo "    feat(<scope>): <summary>" >&2
  echo "    ref(<scope>): <summary>" >&2
  echo "Got: $subject" >&2
  exit 1
fi

if ! grep -q -E '^[[:space:]]*-[[:space:]]+[^[:space:]]' "$message"; then
  echo "Rejected: commit body must list the completed tasks," >&2
  echo "one '- ' bullet per task, from hardest to easiest." >&2
  exit 1
fi

exit 0
